svg.script:
// Folder (relative to this page) that contains the game .html files.
var GAMES_DIR = "games/";

// OPTIONAL: load the games from a GitHub repo (your fork) through jsDelivr
// instead of from the local games/ folder. Example:
//   var REMOTE_BASE = "https://cdn.jsdelivr.net/gh/YOURUSERNAME/html@main/";
// Leave it as "" to use the local folder. Games marked "direct" (the two
// large Eaglercraft clients) always load from the local folder.
var REMOTE_BASE = "https://cdn.jsdelivr.net/gh/GabeDude505/ma-thal-gebra@main/";
var blobUrl = null;
function gameUrl(g) { if (g.url) return g.url; return (REMOTE_BASE && !g.direct ? REMOTE_BASE : GAMES_DIR) + g.file; }

var games = [], favs = new Set(), current = null;
var $ = function (s) { return document.querySelector(s); };

try { favs = new Set(JSON.parse(localStorage.getItem("favs") || "[]")); } catch (e) {}
function saveFavs() { try { localStorage.setItem("favs", JSON.stringify(Array.from(favs))); } catch (e) {} }

function hue(id) { return (id * 47) % 360; }
function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }

function render() {
  var q = $("#q").value.trim().toLowerCase();
  var onlyNamed = $("#onlyNamed").checked, onlyFav = $("#onlyFav").checked;
  var list = games.filter(function (g) {
    if (onlyNamed && !g.named) return false;
    if (onlyFav && !favs.has(g.id)) return false;
    return !q || g.name.toLowerCase().indexOf(q) !== -1 || String(g.id) === q;
  });
  if ($("#sort").value === "az") list.sort(function (a, b) { return a.name.localeCompare(b.name); });
  else list.sort(function (a, b) { return b.id - a.id; });
  $("#count").textContent = list.length + " games";
  $("#empty").hidden = list.length > 0;
  var html = "";
  list.forEach(function (g) {
    html += '<div class="cardwrap"><button class="card" data-id="' + g.id + '">' +
      '<div class="tile" style="background:linear-gradient(135deg,hsl(' + hue(g.id) + ',65%,52%),hsl(' + ((hue(g.id) + 40) % 360) + ',65%,38%))">' +
      esc(g.name.charAt(0).toUpperCase()) + '</div><div class="name">' + esc(g.name) + '</div></button>' +
      '<button class="star' + (favs.has(g.id) ? " on" : "") + '" data-fav="' + g.id + '" aria-label="Favorite">' + (favs.has(g.id) ? "★" : "☆") + '</button></div>';
  });
  $("#grid").innerHTML = html;
}

// Remove the analytics snippet that is injected at the top of these files.
function stripTracking(src) {
  return src
    .replace(/<script[^>]*googletagmanager\.com[^>]*><\/script>/gi, "")
    .replace(/<script>\s*window\.dataLayer[\s\S]*?gtag\('config'[^)]*\);\s*<\/script>/gi, "");
}

function openGame(g) {
  if (blobUrl) { URL.revokeObjectURL(blobUrl); blobUrl = null; }
  current = g;
  location.hash = "play=" + g.id;
  $("#title").textContent = g.name;
  $("#player").classList.add("open");
  $("#loading").style.display = "grid";
  var old = $("#frameWrap iframe"); if (old) old.remove();
  var f = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
  f.setAttribute("allow", "fullscreen; autoplay; gamepad; clipboard-write; clipboard-read; accelerometer; gyroscope; keyboard-map");
  f.setAttribute("allowfullscreen", "");
  f.setAttribute("tabindex", "0");
  var url = gameUrl(g);
  f.onload = function () { $("#loading").style.display = "none"; focusGame(); };
  $("#frameWrap").appendChild(f);
  // "dir" in gams.json = a folder holding a multi-file game (index.html plus its assets).
  // The page is fetched and run with <base> pointing at the folder, so it works even when the
  // host (for example jsDelivr) serves .html files as plain text.
  if (g.dir) {
    var dir = new URL(g.dir, location.href).href;
    var entry = dir + (g.entry || "index.html");
    fetch(entry).then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); }).then(function (t) {
      if (current !== g) return;
      var base = '<base href="' + dir + '">';
      t = /<head[^>]*>/i.test(t) ? t.replace(/<head[^>]*>/i, function (m) { return m + base; }) : base + t;
      blobUrl = URL.createObjectURL(new Blob([t], { type: "text/html" }));
      f.src = blobUrl;
    }).catch(function () { if (current === g) f.src = entry; });
    return;
  }
  // "url" in gams.json = a full address on a host that serves real HTML: embed it directly.
  if (g.url) { f.src = url; return; }
  // Large single-file clients: fetch as a blob and run it as HTML, so it works even when the
  // host (for example jsDelivr) serves .html files as plain text.
  if (g.direct) {
    fetch(url).then(function (r) { if (!r.ok) throw new Error(r.status); return r.blob(); }).then(function (b) {
      if (current !== g) return;
      blobUrl = URL.createObjectURL(new Blob([b], { type: "text/html" }));
      f.src = blobUrl;
    }).catch(function () { if (current === g) f.src = url; });
    return;
  }
  fetch(url).then(function (r) {
    if (!r.ok) throw new Error(r.status);
    return r.text();
  }).then(function (t) {
    if (current !== g) return;
    f.srcdoc = stripTracking(t);
  }).catch(function () {
    if (current === g) f.src = url;
  });
}

function closeGame() {
  current = null;
  if (blobUrl) { URL.revokeObjectURL(blobUrl); blobUrl = null; }
  $("#player").classList.remove("open");
  var f = $("#frameWrap iframe"); if (f) f.remove();
  if (location.hash) history.replaceState(null, "", location.pathname + location.search);
}

$("#grid").addEventListener("click", function (e) {
  var s = e.target.closest("[data-fav]");
  if (s) {
    var id = +s.dataset.fav;
    if (favs.has(id)) favs.delete(id); else favs.add(id);
    saveFavs(); render(); return;
  }
  var c = e.target.closest("[data-id]");
  if (c) openGame(games.find(function (g) { return g.id === +c.dataset.id; }));
});
$("#close").onclick = closeGame;
$("#fs").onclick = function () {
  var f = $("#frameWrap iframe"); if (f && f.requestFullscreen) f.requestFullscreen();
  focusGame();
};
$("#newtab").onclick = function () {
  if (!current) return;
  // Hosts such as jsDelivr serve .html as plain text, so reopen this launcher on the game instead.
  window.open(location.pathname + location.search + "#play=" + current.id, "_blank", "noopener");
};
// Esc no longer closes the game (it belongs to the game: it opens the pause menu).
// Keep keyboard focus inside the game so WASD and every other key reaches it.
function focusGame() {
  var f = $("#frameWrap iframe");
  if (f) { try { f.focus(); if (f.contentWindow) f.contentWindow.focus(); } catch (e) {} }
}
$("#frameWrap").addEventListener("mouseenter", focusGame);
$("#frameWrap").addEventListener("pointerdown", focusGame);
window.addEventListener("focus", function () { if (current) setTimeout(focusGame, 0); });
["#q", "#sort", "#onlyNamed", "#onlyFav"].forEach(function (s) { $(s).addEventListener("input", render); });

fetch("gams.json").then(function (r) { return r.json(); }).then(function (data) {
  games = data; render();
  var m = location.hash.match(/play=(\d+)/);
  if (m) { var g = games.find(function (x) { return x.id === +m[1]; }); if (g) openGame(g); }
}).catch(function () {
  $("#empty").hidden = false;
  $("#empty").textContent = "Could not load gams.json. Serve this folder over http(s) rather than opening the file directly.";
});
